import React, { useEffect, useState } from 'react';
import { getStats, getUsers } from '../services/adminService';
import { getRequests } from '../services/requestService';
import { toast } from 'react-toastify';
import { FiUsers, FiFileText, FiClock, FiCheckCircle, FiXCircle, FiAlertCircle, FiTrendingUp, FiActivity, FiCalendar, FiRefreshCw, FiFilter, FiSearch, FiSettings, FiShield, FiZap, FiTarget, FiBarChart2, FiPieChart, FiUserX, FiMoreVertical, FiDownload, FiBriefcase, FiAward, FiGitBranch, FiTrendingDown, FiPercent } from 'react-icons/fi';
import { Line, Doughnut, Bar, Pie } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, BarElement } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, BarElement);

const Statistics = () => {
  const [stats, setStats] = useState({});
  const [users, setUsers] = useState([]);
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterPeriod, setFilterPeriod] = useState('all');

  useEffect(() => {
    loadData();
    if (autoRefresh) {
      const intervalId = setInterval(() => {
        loadData();
      }, 30000); // Refresh every 30 seconds
      return () => clearInterval(intervalId);
    }
  }, [autoRefresh]);

  const loadData = async () => {
    try {
      const statsData = await getStats();
      setStats(statsData);
      
      const requestsData = await getRequests();
      setRequests(requestsData);
      
      const usersData = await getUsers();
      setUsers(usersData);
    } catch (error) {
      toast.error('Erreur lors du chargement des statistiques');
    } finally {
      setLoading(false);
    }
  };

  const filteredRequests = requests.filter(req => {
    const matchesSearch = req.reference.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          req.workflowType.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch;
  });

  // Calculate additional statistics
  const calculateStats = () => {
    const totalUsers = users.length;
    const activeUsers = users.filter(u => u.isActive).length;
    const inactiveUsers = totalUsers - activeUsers;
    
    const totalRequests = requests.length;
    const approvedRequests = requests.filter(r => r.status === 'approved').length;
    const rejectedRequests = requests.filter(r => r.status === 'rejected').length;
    const pendingRequests = requests.filter(r => r.status === 'pending').length;
    const inProgressRequests = requests.filter(r => r.status === 'in_progress').length;
    const returnedRequests = requests.filter(r => r.status === 'returned').length;
    
    const adminCount = users.filter(u => u.role === 'admin').length;
    const validatorCount = users.filter(u => u.role === 'validator').length;
    const employeeCount = users.filter(u => u.role === 'employee').length;
    
    const departments = [...new Set(users.map(u => u.department).filter(Boolean))];
    const avgRequestsPerUser = totalUsers > 0 ? (totalRequests / totalUsers).toFixed(2) : 0;
    
    return {
      totalUsers,
      activeUsers,
      inactiveUsers,
      totalRequests,
      approvedRequests,
      rejectedRequests,
      pendingRequests,
      inProgressRequests,
      returnedRequests,
      adminCount,
      validatorCount,
      employeeCount,
      departments,
      avgRequestsPerUser
    };
  };

  const calculatedStats = calculateStats();

  // Chart data
  const monthlyData = () => {
    const monthLabels = ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Juin', 'Juil', 'Aoû', 'Sep', 'Oct', 'Nov', 'Déc'];
    const requestsByMonth = new Array(12).fill(0);
    const approvalsByMonth = new Array(12).fill(0);
    
    requests.forEach((request) => {
      if (!request.createdAt) return;
      const monthIndex = new Date(request.createdAt).getMonth();
      if (monthIndex >= 0 && monthIndex < 12) {
        requestsByMonth[monthIndex] += 1;
        if (request.status === 'approved') {
          approvalsByMonth[monthIndex] += 1;
        }
      }
    });

    return {
      labels: monthLabels,
      datasets: [
        {
          label: 'Demandes créées',
          data: requestsByMonth,
          borderColor: 'rgb(59,130,246)',
          backgroundColor: 'rgba(59,130,246,0.2)',
          tension: 0.2,
        },
        {
          label: 'Demandes approuvées',
          data: approvalsByMonth,
          borderColor: 'rgb(16,185,129)',
          backgroundColor: 'rgba(16,185,129,0.2)',
          tension: 0.2,
        }
      ]
    };
  };

  const statusData = {
    labels: ['Approuvées', 'Rejetées', 'En attente', 'En cours', 'Retournées'],
    datasets: [{
      data: [
        calculatedStats.approvedRequests,
        calculatedStats.rejectedRequests,
        calculatedStats.pendingRequests,
        calculatedStats.inProgressRequests,
        calculatedStats.returnedRequests
      ],
      backgroundColor: ['#10b981', '#ef4444', '#f59e0b', '#3b82f6', '#8b5cf6'],
      borderWidth: 2,
      borderColor: '#ffffff'
    }]
  };

  const roleData = {
    labels: ['Admins', 'Validateurs', 'Employés'],
    datasets: [{
      data: [calculatedStats.adminCount, calculatedStats.validatorCount, calculatedStats.employeeCount],
      backgroundColor: ['#ef4444', '#3b82f6', '#10b981'],
      borderWidth: 2,
      borderColor: '#ffffff'
    }]
  };

  const departmentData = () => {
    const deptCounts = {};
    users.forEach(user => {
      if (user.department) {
        deptCounts[user.department] = (deptCounts[user.department] || 0) + 1;
      }
    });

    return {
      labels: Object.keys(deptCounts),
      datasets: [{
        data: Object.values(deptCounts),
        backgroundColor: [
          '#3b82f6', '#ef4444', '#10b981', '#f59e0b', 
          '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16'
        ],
        borderWidth: 2,
        borderColor: '#ffffff'
      }]
    };
  };

  const statCards = [
    { title: 'Total Utilisateurs', value: calculatedStats.totalUsers, tone: 'slate', icon: <FiUsers className="w-6 h-6" />, trend: '+12%' },
    { title: 'Utilisateurs Actifs', value: calculatedStats.activeUsers, tone: 'green', icon: <FiShield className="w-6 h-6" />, trend: '+8%' },
    { title: 'Total Demandes', value: calculatedStats.totalRequests, tone: 'blue', icon: <FiFileText className="w-6 h-6" />, trend: '+15%' },
    { title: 'Demandes Approuvées', value: calculatedStats.approvedRequests, tone: 'emerald', icon: <FiCheckCircle className="w-6 h-6" />, trend: '+5%' },
    { title: 'Demandes Rejetées', value: calculatedStats.rejectedRequests, tone: 'red', icon: <FiXCircle className="w-6 h-6" />, trend: '-2%' },
    { title: 'En Attente', value: calculatedStats.pendingRequests, tone: 'amber', icon: <FiClock className="w-6 h-6" />, trend: '+3%' },
    { title: 'En Cours', value: calculatedStats.inProgressRequests, tone: 'blue', icon: <FiActivity className="w-6 h-6" />, trend: '+7%' },
    { title: 'Retournées', value: calculatedStats.returnedRequests, tone: 'purple', icon: <FiAlertCircle className="w-6 h-6" />, trend: '+1%' },
  ];

  const performanceCards = [
    { title: 'Taux d\'Approbation', value: calculatedStats.totalRequests > 0 ? `${((calculatedStats.approvedRequests / calculatedStats.totalRequests) * 100).toFixed(1)}%` : '0%', tone: 'emerald', icon: <FiPercent className="w-6 h-6" /> },
    { title: 'Moyenne/Demande', value: calculatedStats.avgRequestsPerUser, tone: 'blue', icon: <FiBarChart2 className="w-6 h-6" /> },
    { title: 'Départements', value: calculatedStats.departments.length, tone: 'purple', icon: <FiBriefcase className="w-6 h-6" /> },
    { title: 'Admins', value: calculatedStats.adminCount, tone: 'red', icon: <FiAward className="w-6 h-6" /> },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-violet-600 via-purple-600 to-indigo-700">
      {/* Animated Background Elements */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div className="absolute -top-40 -right-40 w-80 h-80 bg-purple-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob"></div>
        <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-indigo-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob animation-delay-2000"></div>
        <div className="absolute top-40 left-40 w-80 h-80 bg-violet-300 rounded-full mix-blend-multiply filter blur-xl opacity-70 animate-blob animation-delay-4000"></div>
      </div>

      {/* Header */}
      <div className="relative bg-white/10 backdrop-blur-xl border-b border-white/20 sticky top-0 z-10">
        <div className="container mx-auto px-4 py-6">
          <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
            <div>
              <h1 className="text-4xl font-black bg-gradient-to-r from-white to-purple-200 bg-clip-text text-transparent flex items-center gap-3">
                <FiBarChart2 className="text-white" />
                Statistiques Globales
              </h1>
              <p className="text-purple-100 mt-2 text-lg font-medium">Vue d'ensemble complète des performances du système</p>
            </div>
            <div className="flex flex-col sm:flex-row gap-3">
              <div className="relative">
                <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-purple-200 w-5 h-5" />
                <input
                  type="text"
                  placeholder="Rechercher..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-3 bg-white/20 border border-white/30 rounded-xl focus:ring-2 focus:ring-purple-400 focus:border-transparent outline-none transition-all text-white placeholder-purple-200 backdrop-blur-sm"
                />
              </div>
              <select
                value={filterPeriod}
                onChange={(e) => setFilterPeriod(e.target.value)}
                className="px-4 py-3 bg-white/20 border border-white/30 rounded-xl focus:ring-2 focus:ring-purple-400 focus:border-transparent outline-none transition-all text-white backdrop-blur-sm"
              >
                <option value="all" className="text-gray-800">Toutes les périodes</option>
                <option value="today" className="text-gray-800">Aujourd'hui</option>
                <option value="week" className="text-gray-800">Cette semaine</option>
                <option value="month" className="text-gray-800">Ce mois</option>
              </select>
              <button
                onClick={() => setAutoRefresh(!autoRefresh)}
                className={`px-4 py-3 rounded-xl border transition-all flex items-center gap-2 backdrop-blur-sm ${
                  autoRefresh 
                    ? 'bg-green-500/30 text-green-100 border-green-400/50' 
                    : 'bg-white/20 text-white border-white/30'
                }`}
              >
                <FiRefreshCw className={`w-4 h-4 ${autoRefresh ? 'animate-spin' : ''}`} />
                Auto
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="relative container mx-auto px-4 py-8">
        {/* Main Statistics Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {statCards.map((card, index) => (
            <div
              key={card.title}
              className="group relative bg-white/10 backdrop-blur-xl rounded-2xl border border-white/20 p-6 hover:bg-white/20 transition-all duration-500 transform hover:scale-105 hover:shadow-2xl animate-slideIn"
              style={{ animationDelay: `${index * 100}ms` }}
            >
              {/* Glow effect */}
              <div className="absolute inset-0 bg-gradient-to-r from-purple-600/20 to-indigo-600/20 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-500"></div>
              
              <div className="relative z-10">
                <div className="flex items-start justify-between mb-4">
                  <div className="p-3 bg-white/20 rounded-xl backdrop-blur-sm group-hover:bg-white/30 transition-colors duration-300">
                    <div className="text-white">{card.icon}</div>
                  </div>
                  <span className={`text-xs font-bold px-3 py-1 rounded-full backdrop-blur-sm ${
                    card.trend.startsWith('+') ? 'bg-green-500/30 text-green-100 border border-green-400/50' : 'bg-red-500/30 text-red-100 border border-red-400/50'
                  }`}>
                    {card.trend}
                  </span>
                </div>
                <h3 className="text-white/80 text-sm font-medium mb-2">{card.title}</h3>
                <p className="text-white text-3xl font-black">{card.value}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Performance Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {performanceCards.map((card, index) => (
            <div
              key={card.title}
              className="group relative bg-gradient-to-br from-white/10 to-white/5 backdrop-blur-xl rounded-2xl border border-white/20 p-6 hover:from-white/20 hover:to-white/10 transition-all duration-500 transform hover:scale-105 hover:shadow-2xl animate-slideIn"
              style={{ animationDelay: `${index * 100 + 800}ms` }}
            >
              {/* Shimmer effect */}
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-1000 animate-shimmer"></div>
              
              <div className="relative z-10">
                <div className="flex items-start justify-between mb-4">
                  <div className="p-3 bg-gradient-to-br from-white/20 to-white/10 rounded-xl backdrop-blur-sm group-hover:from-white/30 group-hover:to-white/20 transition-all duration-300">
                    <div className="text-white">{card.icon}</div>
                  </div>
                </div>
                <h3 className="text-white/80 text-sm font-medium mb-2">{card.title}</h3>
                <p className="text-white text-2xl font-black">{card.value}</p>
              </div>
            </div>
          ))}
        </div>

        {/* Charts Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
          {/* Monthly Trends */}
          <div className="group bg-white/10 backdrop-blur-xl rounded-2xl border border-white/20 p-6 hover:bg-white/20 transition-all duration-500 transform hover:scale-[1.02] animate-slideIn">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-black text-white flex items-center gap-3">
                <div className="p-2 bg-gradient-to-br from-blue-500/30 to-indigo-500/30 rounded-xl backdrop-blur-sm">
                  <FiTrendingUp className="w-5 h-5 text-white" />
                </div>
                Tendances Mensuelles
              </h2>
              <button className="p-3 bg-white/10 rounded-xl hover:bg-white/20 transition-colors group-hover:rotate-180 duration-500">
                <FiMoreVertical className="w-5 h-5 text-white" />
              </button>
            </div>
            <div className="h-80">
              <Line 
                data={monthlyData()} 
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      position: 'bottom',
                      labels: {
                        color: 'white',
                        font: {
                          size: 12,
                          weight: 'bold'
                        }
                      }
                    }
                  },
                  scales: {
                    y: {
                      beginAtZero: true,
                      grid: {
                        color: 'rgba(255, 255, 255, 0.1)'
                      },
                      ticks: {
                        color: 'white'
                      }
                    },
                    x: {
                      grid: {
                        display: false
                      },
                      ticks: {
                        color: 'white'
                      }
                    }
                  }
                }}
              />
            </div>
          </div>

          {/* Status Distribution */}
          <div className="group bg-white/10 backdrop-blur-xl rounded-2xl border border-white/20 p-6 hover:bg-white/20 transition-all duration-500 transform hover:scale-[1.02] animate-slideIn">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-black text-white flex items-center gap-3">
                <div className="p-2 bg-gradient-to-br from-green-500/30 to-emerald-500/30 rounded-xl backdrop-blur-sm">
                  <FiPieChart className="w-5 h-5 text-white" />
                </div>
                Répartition par Statut
              </h2>
              <button className="p-3 bg-white/10 rounded-xl hover:bg-white/20 transition-colors group-hover:rotate-180 duration-500">
                <FiMoreVertical className="w-5 h-5 text-white" />
              </button>
            </div>
            <div className="h-80">
              <Doughnut 
                data={statusData} 
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      position: 'bottom',
                      labels: {
                        color: 'white',
                        font: {
                          size: 12,
                          weight: 'bold'
                        }
                      }
                    }
                  }
                }}
              />
            </div>
          </div>
        </div>

        {/* Secondary Charts */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Role Distribution */}
          <div className="group bg-white/10 backdrop-blur-xl rounded-2xl border border-white/20 p-6 hover:bg-white/20 transition-all duration-500 transform hover:scale-[1.02] animate-slideIn">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-black text-white flex items-center gap-3">
                <div className="p-2 bg-gradient-to-br from-purple-500/30 to-pink-500/30 rounded-xl backdrop-blur-sm">
                  <FiUsers className="w-5 h-5 text-white" />
                </div>
                Répartition par Rôle
              </h2>
              <button className="p-3 bg-white/10 rounded-xl hover:bg-white/20 transition-colors group-hover:rotate-180 duration-500">
                <FiMoreVertical className="w-5 h-5 text-white" />
              </button>
            </div>
            <div className="h-80">
              <Pie 
                data={roleData} 
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      position: 'bottom',
                      labels: {
                        color: 'white',
                        font: {
                          size: 12,
                          weight: 'bold'
                        }
                      }
                    }
                  }
                }}
              />
            </div>
          </div>

          {/* Department Distribution */}
          <div className="group bg-white/10 backdrop-blur-xl rounded-2xl border border-white/20 p-6 hover:bg-white/20 transition-all duration-500 transform hover:scale-[1.02] animate-slideIn">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-black text-white flex items-center gap-3">
                <div className="p-2 bg-gradient-to-br from-orange-500/30 to-amber-500/30 rounded-xl backdrop-blur-sm">
                  <FiBriefcase className="w-5 h-5 text-white" />
                </div>
                Répartition par Département
              </h2>
              <button className="p-3 bg-white/10 rounded-xl hover:bg-white/20 transition-colors group-hover:rotate-180 duration-500">
                <FiMoreVertical className="w-5 h-5 text-white" />
              </button>
            </div>
            <div className="h-80">
              <Bar 
                data={departmentData()} 
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      display: false
                    }
                  },
                  scales: {
                    y: {
                      beginAtZero: true,
                      grid: {
                        color: 'rgba(255, 255, 255, 0.1)'
                      },
                      ticks: {
                        color: 'white'
                      }
                    },
                    x: {
                      grid: {
                        display: false
                      },
                      ticks: {
                        color: 'white'
                      }
                    }
                  }
                }}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Statistics;
